                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    #!/usr/bin/env python3
"""
vacuum_scheduler.py - Periodic database optimization scheduler.

Runs VACUUM on all session databases to reclaim space and optimize performance.
Can be run manually or scheduled via cron/task scheduler.

Usage:
  python vacuum_scheduler.py --dry-run
  python vacuum_scheduler.py --all
  python vacuum_scheduler.py --db-path .ai-activity/ai-sessions/<developer>/sessions.db
"""

import argparse
import os
import sqlite3
import sys

sys.path.insert(0, os.path.join(os.path.dirname(os.path.abspath(__file__)), '..', 'ai-sessions', 'shared'))


def get_databases(base_dir):
    """Find all session database files."""
    databases = []
    for root, dirs, files in os.walk(base_dir):
        for f in files:
            if f.endswith('.db'):
                databases.append(os.path.join(root, f))
    return databases


def vacuum_database(db_path, dry_run=False):
    """Run VACUUM on a database."""
    try:
        conn = sqlite3.connect(db_path)
        
        # Get size before
        size_before = os.path.getsize(db_path)
        
        if dry_run:
            print(f"  Would vacuum: {db_path} ({size_before / 1024 / 1024:.1f} MB)")
            conn.close()
            return True
        
        conn.execute('VACUUM')
        conn.execute('PRAGMA integrity_check')
        result = conn.execute('PRAGMA integrity_check').fetchone()[0]
        conn.close()
        
        size_after = os.path.getsize(db_path)
        saved = size_before - size_after
        
        if result == 'ok':
            print(f"  Vacuumed: {db_path} ({size_before / 1024 / 1024:.1f} MB -> {size_after / 1024 / 1024:.1f} MB, saved {saved / 1024 / 1024:.1f} MB)")
            return True
        else:
            print(f"  Integrity check failed for {db_path}: {result}")
            return False
    except Exception as e:
        print(f"  Error vacuuming {db_path}: {e}")
        return False


def main():
    parser = argparse.ArgumentParser(
        description='Periodic database optimization scheduler.'
    )
    parser.add_argument('--db-path', default=None,
                        help='Path to specific database')
    parser.add_argument('--all', action='store_true',
                        help='Vacuum all session databases')
    parser.add_argument('--dry-run', action='store_true',
                        help='Show what would be vacuumed')
    parser.add_argument('--base-dir', default='.ai-activity/ai-sessions',
                        help='Base directory for session databases')
    
    args = parser.parse_args()
    
    if args.dry_run:
        print("DRY RUN MODE")
    elif args.all:
        print("Vacuuming all session databases...")
    else:
        print("Vacuuming specified database...")
    
    if args.db_path:
        databases = [args.db_path]
    elif args.all:
        databases = get_databases(args.base_dir)
    else:
        print("ERROR: Must specify --db-path or --all")
        sys.exit(1)
    
    if not databases:
        print("No databases found.")
        sys.exit(0)
    
    success = 0
    failed = 0
    
    for db_path in databases:
        if vacuum_database(db_path, args.dry_run):
            success += 1
        else:
            failed += 1
    
    print(f"\nComplete: {success} succeeded, {failed} failed")
    
    if failed > 0:
        sys.exit(1)


if __name__ == '__main__':
    main()
